package com.nook.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Service public class JwtService { private final javax.crypto.SecretKey key; private final long minutes; public JwtService(@Value("${nook.jwt-secret}") String secret,@Value("${nook.access-minutes}") long minutes){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.minutes=minutes;} public String issue(UUID id){Instant now=Instant.now();return Jwts.builder().subject(id.toString()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(minutes,ChronoUnit.MINUTES))).signWith(key).compact();} public UUID parse(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} public long expiresSeconds(){return minutes*60;} }
